class LockGuard implements Disposable {
  constructor(private readonly release: () => void) {}
  [Symbol.dispose]() { this.release(); }
}
function scoped(m: Mutex): LockGuard {
  return new LockGuard(m.acquire());   // async-mutex style synchronous acquire
}
function transfer(cents: number) {
  using gate = scoped(ledgerMutex);    // released at scope exit, even on throw
  balance += cents;
}

