import { AsyncLocalStorage } from "node:async_hooks";
const tx = new AsyncLocalStorage<Transaction>();

export function transaction<T>(fn: () => Promise<T>): Promise<T> {
  return db.begin().then((t) =>
    tx.run(t, fn).then(
      (r) => t.commit().then(() => r),
      (e) => t.rollback().then(() => Promise.reject(e)),
    ));
}
